PRAGMA foreign_keys=ON;
CREATE TABLE teams(team_id INTEGER PRIMARY KEY,region INTEGER NOT NULL CHECK(region IN(1,2)),lead_id INTEGER NOT NULL,FOREIGN KEY(lead_id) REFERENCES people(person_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE people(person_id INTEGER PRIMARY KEY,team_id INTEGER NOT NULL,rank INTEGER NOT NULL CHECK(rank BETWEEN 1 AND 3),UNIQUE(team_id,rank),FOREIGN KEY(team_id) REFERENCES teams(team_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE shifts(shift_id INTEGER PRIMARY KEY,team_id INTEGER NOT NULL,rank INTEGER NOT NULL,FOREIGN KEY(team_id,rank) REFERENCES people(team_id,rank) DEFERRABLE INITIALLY DEFERRED);
